from pathlib import Path
R=Path(__file__).resolve().parent
head='''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="description" content="{title} for Fence Wizards temporary fencing requests."><meta name="robots" content="noindex,nofollow"><meta name="referrer" content="no-referrer"><title>{title} | Fence Wizards</title><link rel="stylesheet" href="/styles.css"><link rel="stylesheet" href="/quotes.css?v=1"><script type="module" src="/{script}.mjs?v=2"></script></head><body><header class="quote-header"><a class="quote-brand" href="/"><img src="/assets/logo.png" alt="Fence Wizards"></a><a href="/estimate/">Back to fence planner</a></header><main class="quote-wrap"><div class="demo-notice" id="demo-notice" hidden><strong>Design preview · fictional example</strong><br>No customer data is stored or sent. Real submissions and staff access require Cloudflare setup.</div>'''
confirmation='''<p class="eyebrow red">Fence Wizards / Quote request</p><h1 id="confirmation-title">Checking your confirmation…</h1><p id="receipt-error" role="status"></p><div id="receipt-content" hidden><div class="confirmation-grid"><section class="quote-panel confirmation-intro"><p class="eyebrow red">Your reference</p><strong class="quote-ref" id="request-id"></strong><p class="quiet" id="request-date"></p><span class="quote-badge" id="confirmation-status"></span><p id="confirmation-message"></p><h2>What happens next?</h2><p>Richard will review the layout and discuss the details with you before confirming the price and installation schedule.</p><p>Need emergency fencing or want to talk through the plan? Call Richard at <a href="tel:+13172964015">(317) 296-4015</a>.</p><div class="quote-actions"><button id="copy-confirmation" type="button">Copy private link</button><button id="print-request" type="button">Print confirmation</button></div><p id="link-expiry" class="quiet"></p><p id="link-message" role="status"></p><input id="private-link" aria-label="Private confirmation link" readonly hidden><p class="quiet">No payment is due through this page. Any payment request comes after Richard confirms the job.</p></section><section class="quote-panel"><h2>Your submitted plan</h2><div id="receipt-project"></div></section></div></div>'''
inbox='''<p class="eyebrow red">Fence Wizards / Staff</p><h1>Quote inbox</h1><p class="quiet">Review the plan. Call the customer. Keep the details together.</p><a id="staff-signout" href="/cdn-cgi/access/logout">Sign out</a><p id="inbox-message" role="status"></p><div class="inbox-layout"><aside class="inbox-sidebar"><form id="search-form" class="inbox-search"><label>Find a request<input id="quote-search" type="search" maxlength="100" placeholder="Reference, name, or address"></label><label>Status<select id="status-filter"><option value="">All requests</option><option value="new">New</option><option value="contacted">Contacted</option><option value="quoted">Quoted</option><option value="closed">Closed</option></select></label><button type="submit">Search requests</button></form><div id="quote-list"></div><div class="inbox-pagination"><button type="button" id="previous-page">Previous</button><span id="page-number">Page 1</span><button type="button" id="next-page">Next</button></div></aside><article class="quote-panel" id="quote-detail" hidden><p class="eyebrow red">Quote request</p><h2 id="detail-id" tabindex="-1"></h2><p class="quiet" id="detail-date"></p><div class="customer-card" id="customer"></div><h3>Customer notes</h3><p id="customer-notes" class="customer-notes"></p><div id="detail-project"></div><div class="quote-actions"><button type="button" id="print-quote">Print request</button><button type="button" id="download-quote">Download record</button></div><form id="quote-edit" class="quote-edit"><label>Request status<select id="edit-status"><option value="new">New</option><option value="contacted">Contacted</option><option value="quoted">Quoted</option><option value="closed">Closed</option></select></label><label>Internal notes<textarea id="internal-notes" rows="5" maxlength="5000" placeholder="Call notes, confirmed details, or invoice reference"></textarea></label><p class="quiet">Internal notes are visible only to authorized staff. The original customer request and preliminary estimate stay unchanged.</p><button type="submit" class="primary" id="save-quote">Save changes</button></form><p id="edit-message" role="status"></p><p class="quiet" id="notify-state"></p><button type="button" id="retry-notify">Retry notification to Richard</button><p class="quiet" id="customer-notify-state"></p><p class="quiet" id="customer-link-state"></p><div class="quote-actions"><button type="button" id="retry-customer">Retry customer confirmation email</button><button type="button" id="revoke-receipt">Disable customer link</button></div></article></div>'''
for path,title,script,body in [('quote-confirmation','Quote Request Confirmation','confirmation',confirmation),('staff/quotes','Quote Inbox','inbox',inbox)]:
 p=R/'dist'/path/'index.html';p.parent.mkdir(parents=True,exist_ok=True);p.write_text(head.format(title=title,script=script)+body+'</main></body></html>',encoding='utf-8')
